        .get_or_init(|| {
            let handle = PrometheusBuilder::new()
                .set_buckets(LATENCY_BUCKETS)
                .expect("static non-empty buckets")
                .install_recorder()
                .expect("global metrics recorder installs once");
            tracing::info!(service, "metrics recorder installed");
            handle
        })
        .clone()
}

